import { Asset } from "expo-asset";
import { File } from "expo-file-system";
import { Platform } from "react-native";
import { createStructuredError } from "@/lib/errors";

// Text asset, not a JS module: keeps the notices out of the startup bundle.
// Generated by `bun run licenses`. Loads when Settings > Licenses opens.
const LICENSES_ASSET = require("../../../assets/licenses.txt");

const loadFailed = (why: string) =>
  createStructuredError({
    status: "licenses_load_failed",
    message: "Licenses could not be loaded",
    why,
    fix: "Open Licenses again. If it fails again, reinstall Pixy",
  });

const readAssetText = async (asset: Asset) => {
  // expo-file-system has no web implementation; the web asset is a URL.
  if (Platform.OS === "web") {
    const response = await fetch(asset.uri);
    if (!response.ok) {
      throw loadFailed(`HTTP ${response.status} for ${asset.uri}`);
    }
    return response.text();
  }
  await asset.downloadAsync();
  if (!asset.localUri) {
    throw loadFailed("assets/licenses.txt has no local URI after download");
  }
  return new File(asset.localUri).text();
};

/**
 * Reads the third-party notices shipped as `assets/licenses.txt`.
 * Rejects with a structured `licenses_load_failed` error.
 */
export const loadLicensesText = async () => {
  try {
    return await readAssetText(Asset.fromModule(LICENSES_ASSET));
  } catch (cause) {
    if (cause instanceof Error && "status" in cause) {
      throw cause;
    }
    throw loadFailed(
      `Reading assets/licenses.txt failed: ${cause instanceof Error ? cause.message : String(cause)}`
    );
  }
};
